// HI11s DEL_VALUE=10; generated by hi11s_gen.py. Board run pending.
module top(input clk_25mhz, input side_input, output ftdi_rxd);
  reg loadn=1, move=0, direction=1;
  wire output_flag, input_flag, delayed_input;
  reg [15:0] warm=0;
  reg run=0;
  reg [11:0] u=0;
  always @(posedge clk_25mhz) begin
    if (!run) begin
      warm<=warm+1'b1;
      if (&warm) run<=1;
    end else if (u<2048) u<=u+1'b1;
  end
  always @(posedge clk_25mhz) if (run) begin
    if (u < 16) begin loadn<=1'b1; move<=(0); direction<=1'b1; end
    else if (u < 576) begin loadn<=1'b1; move<=(u[1:0] == 0); direction<=1'b1; end
    else if (u < 592) begin loadn<=1'b1; move<=(0); direction<=1'b1; end
    else if (u < 600) begin loadn<=1'b1; move<=(0); direction<=1'b0; end
    else if (u < 608) begin loadn<=1'b1; move<=(0); direction<=1'b1; end
    else if (u < 612) begin loadn<=1'b0; move<=(0); direction<=1'b0; end
    else if (u < 616) begin loadn<=1'b1; move<=(0); direction<=1'b0; end
    else if (u < 1176) begin loadn<=1'b1; move<=(u[1:0] == 0); direction<=1'b0; end
    else if (u < 1192) begin loadn<=1'b1; move<=(0); direction<=1'b1; end
    else if (u < 1196) begin loadn<=1'b0; move<=(0); direction<=1'b1; end
    else if (u < 1200) begin loadn<=1'b1; move<=(0); direction<=1'b1; end
    else if (u < 1760) begin loadn<=1'b1; move<=(u[1:0] == 0); direction<=1'b1; end
    else if (u < 1776) begin loadn<=1'b1; move<=(0); direction<=1'b0; end
    else if (u < 2048) begin loadn<=1'b1; move<=(0); direction<=1'b1; end
  end
  DELAYF #(.DEL_MODE("USER_DEFINED"), .DEL_VALUE(10)) input_delay(
    .A(side_input), .Z(delayed_input), .LOADN(loadn), .MOVE(move),
    .DIRECTION(direction), .CFLAG(input_flag));
  // Keep input Z as data in every record, alongside the two CFLAG outputs.
  // byte = {reserved[1:0], delayed_input, LOADN, MOVE, DIRECTION, input_flag, output_flag}.
  wire [7:0] sample={2'b0,delayed_input,loadn,move,direction,input_flag,output_flag};
  reg [7:0] record [0:2047];
  reg [7:0] checksum=0;
  always @(posedge clk_25mhz) if (run && u<2048) begin
    record[u[10:0]]<=sample;
    checksum<=checksum^sample;
  end
  wire done=u==2048;
  function [7:0] hex(input [3:0] v);
    hex=v<10 ? 8'h30+v : 8'h37+v;
  endfunction
  // H11S0, eight sequence digits, 4096 payload digits, XOR byte, CR LF.
  reg [31:0] sequence_number=0;
  reg [12:0] ci=0;
  wire [12:0] payload_index=ci-13;
  wire [10:0] read_address=payload_index[11:1];
  reg [7:0] read_sample=0;
  always @(posedge clk_25mhz) read_sample<=record[read_address];
  reg [7:0] ch;
  always @* begin
    if (ci==0) ch="H";
    else if (ci==1 || ci==2) ch="1";
    else if (ci==3) ch="S";
    else if (ci==4) ch="0";
    else if (ci<13) ch=hex(sequence_number[31-4*(ci-5) -: 4]);
    else if (ci<4109) ch=hex(payload_index[0] ? read_sample[3:0] : read_sample[7:4]);
    else if (ci==4109) ch=hex(checksum[7:4]);
    else if (ci==4110) ch=hex(checksum[3:0]);
    else if (ci==4111) ch=8'h0d;
    else ch=8'h0a;
  end
  (* syn_useioff=0 *) reg tx=1;
  reg busy=0;
  reg [7:0] baud=0;
  reg [3:0] bitn=0;
  reg [9:0] shift=10'h3ff;
  reg [22:0] pause=0;
  reg [1:0] gap=2;
  always @(posedge clk_25mhz)
    if (!busy) begin
      if (pause!=0) pause<=pause-1'b1;
      else if (gap!=0) gap<=gap-1'b1;
      else if (done) begin
        shift<={1'b1,ch,1'b0};
        busy<=1; baud<=0; bitn<=0;
      end
    end else if (baud==216) begin
      baud<=0; tx<=shift[0]; shift<={1'b1,shift[9:1]}; bitn<=bitn+1'b1;
      if (bitn==9) begin
        busy<=0; gap<=2;
        if (ci==4112) begin
          ci<=0; sequence_number<=sequence_number+1'b1; pause<=23'd2500000;
        end else ci<=ci+1'b1;
      end
    end else baud<=baud+1'b1;
  wire registered_tx;
  OFS1P3BX tx_reg(.SCLK(clk_25mhz), .SP(1'b1), .PD(1'b0),
                    .D(tx), .Q(registered_tx));
  DELAYF #(.DEL_MODE("USER_DEFINED"), .DEL_VALUE(10)) output_delay(
    .A(registered_tx), .Z(ftdi_rxd), .LOADN(loadn), .MOVE(move),
    .DIRECTION(direction), .CFLAG(output_flag));
endmodule
